bounded_host_request.command:
set -euo pipefail
name=gace-createvdobot-videobot-poll-1
test "$(docker inspect -f '{{.State.Running}}' "$name" 2>/dev/null)" = true || exit 61
docker exec -i "$name" node --input-type=module - <<'NODE'
import pg from 'pg';
import{readFileSync}from'node:fs';
const e=process.env;
const pool=new pg.Pool({host:e.VIDEOBOT_DB_HOST,database:e.VIDEOBOT_DB_NAME,user:e.VIDEOBOT_DB_USER,password:readFileSync(e.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim(),max:1});
try{
 const cur=await pool.query("SELECT last_update_id FROM videobot_poll_cursor WHERE consumer_id='createvdobot'");
 const cursor=Number(cur.rows[0]?.last_update_id??-1);
 const bad=await pool.query("SELECT update_id,status FROM videobot_webhook_updates WHERE update_id>$1 AND status<>'completed' ORDER BY update_id ASC LIMIT 5",[cursor]);
 console.log('STK_POLL_CURSOR_PRESENT='+(cursor>=0));
 if(bad.rowCount){
  console.log('STK_POLL_UNRESOLVED_AFTER_CURSOR=YES');
  process.exitCode=81;
 }else{
  const user=await pool.query("SELECT s.state->>'screen' AS screen,s.screen_message_id FROM videobot_sticker_products p LEFT JOIN videobot_creator_sessions s ON s.owner_user_id=p.seller_user_id WHERE p.product_id=$1",['sp_76f23430d1c29ca355960a95']);
  if(user.rowCount!==1){process.exitCode=82;}
  else{
   console.log('STK_SELLER_SESSION_SCREEN='+(user.rows[0].screen??'NONE'));
   console.log('STK_SELLER_SCREEN_MESSAGE_PRESENT='+Boolean(user.rows[0].screen_message_id));
   console.log('STK_POLL_UNRESOLVED_AFTER_CURSOR=NO');
  }
 }
}finally{await pool.end();}
NODE
echo STK_POLL_STATE_READBACK=PASS
